declare(strict_types=1);require_once __DIR__.'/../includes/layout.php';require_login();$id=filter_input(INPUT_GET,'event',FILTER_VALIDATE_INT);$s=db()->prepare('SELECT * FROM events WHERE id=?');$s->execute([$id]);$event=$s->fetch();if(!$event){http_response_code(404);exit('ไม่พบกิจกรรม');}$s=db()->prepare('SELECT id,file_name FROM photos WHERE event_id=? AND is_visible=1 ORDER BY id DESC');$s->execute([$id]);$photos=$s->fetchAll();page_header('พิมพ์ QR',true);require __DIR__.'/_nav.php';?><div class="actions no-print"><button class="btn" onclick="window.print()">พิมพ์</button><a class="btn secondary" href="<?=e(url('admin/events.php'))?>">กลับ</a></div><h1>QR Code: <?=e($event['title'])?></h1><div class="qr-sheet"><div class="qr-card"><h2>ค้นหารูปด้วยใบหน้า</h2><div class="qr" data-qr="<?=e(absolute_url('find.php?event='.$event['id']))?>"></div><p><?=e(absolute_url('find.php?event='.$event['id']))?></p></div><?php foreach($photos as $photo):?><div class="qr-card"><strong><?=e($photo['file_name'])?></strong><div class="qr" data-size="140" data-qr="<?=e(absolute_url('download.php?id='.$photo['id']))?>"></div></div><?php endforeach?></div><?php page_footer();?>
